import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{at as i,ct as a,dt as o,ft as s,it as c,lt as l,mt as u,ot as d,pt as f,rt as p,st as m,ut as h}from"./chunks/assets.DAjhvrpn.js";var g=JSON.parse(`{"title":"Ephys/Imaging Automation Pipeline","description":"","frontmatter":{"title":"Ephys/Imaging Automation Pipeline","lang":"en-US"},"headers":[],"relativePath":"software/automation_pipeline.md","filePath":"software/automation_pipeline.md"}`),_={name:`software/automation_pipeline.md`};function v(n,g,_,v,y,b){return e(),r(`div`,null,[...g[0]||=[t(`<h1 id="ephys-imaging-automation-pipeline" tabindex="-1">Ephys/Imaging Automation Pipeline <a class="header-anchor" href="#ephys-imaging-automation-pipeline" aria-label="Permalink to “Ephys/Imaging Automation Pipeline”">​</a></h1><h2 id="data-folders" tabindex="-1">Data Folders <a class="header-anchor" href="#data-folders" aria-label="Permalink to “Data Folders”">​</a></h2><p>The ephys and imaging pipelines use the following data folder structures:</p><ul><li><strong>Raw Data Directory Imaging:</strong> braininit/Data/Raw/imaging/(user)/(subject)/(session_date)_g(session#)/(user_defined_dir)</li><li><strong>Processed Data Directory Imaging:</strong> braininit/Data/Processed/imaging/(user)/(subject)/(session_date)<em>g(session#)/(user_defined_dir)/job_id</em>(jobid)/suite2p_output/suite2p</li><li><strong>Raw Data Directory Ephys:</strong> braininit/Data/Raw/electrophysiology/(user)/(subject)/(session_date)_g(session#)/(g#_spikeglx_dir)/(imec#_spikeglx_dir)</li><li><strong>Processed Data Directory Ephys:</strong> braininit/Data/Processed/electrophysiology/(user)/(subject)/(session_date)_g(session#)/(g#_spikeglx_dir)/(imec#<em>spikeglx_dir)/job_id</em>(jobid)/(sorter)_output</li></ul><h2 id="initial-configuration" tabindex="-1">Initial configuration <a class="header-anchor" href="#initial-configuration" aria-label="Permalink to “Initial configuration”">​</a></h2><p>Note: These steps are only needed if a red label reading &quot;Configuration needed&quot; appears in the top-right corner of the GUI.</p><figure><img src="`+u+`" alt="Configuration needed label" width="542" height="306" loading="lazy"><figcaption>Configuration needed label</figcaption></figure><figure><img src="`+f+`" alt="Configuration screen" width="3666" height="1528" loading="lazy"><figcaption>Configuration screen</figcaption></figure><ol><li>Switch to the <strong>&quot;System Configuration&quot;</strong> tab.</li><li>Click the <strong>&quot;Start Configuration&quot;</strong> button.</li><li>In the <strong>&quot;System Name&quot;</strong> dropdown, select the corresponding system (normally named room#-Recording#).</li><li>In the <strong>&quot;Associated Behavior Rig&quot;</strong> dropdown, select the corresponding rig paired with the recording system.</li><li>Click the <strong>&quot;Add Rig to System&quot;</strong> button.</li><li>Repeat steps 4 and 5 until all rigs associated with the recording system are added.</li><li>In the <strong>&quot;Recording Modality&quot;</strong> dropdown, select the corresponding modality of the recording system.</li><li>In the <strong>&quot;Recording Root Folder&quot;</strong> area, click the folder button to search for the parent path where all recordings will be stored.</li><li>Click the <strong>&quot;Configure System&quot;</strong> button.</li></ol><figure><img src="`+s+`" alt="System configured correctly" width="604" height="320" loading="lazy"><figcaption>System configured correctly</figcaption></figure><p>If something was configured incorrectly, you can repeat the entire process.</p><h2 id="automation-gui-regular-use-manual" tabindex="-1">Automation GUI &quot;regular use&quot; Manual <a class="header-anchor" href="#automation-gui-regular-use-manual" aria-label="Permalink to “Automation GUI &quot;regular use&quot; Manual”">​</a></h2><ul><li>The automation GUI is located on the desktop of every microscope/ephys recording system across BRAIN CoGS. You can identify it by the BRAIN CoGS desktop icon called &quot;Recording_Automation_GUI&quot;.</li><li>We encourage you to register and process every recording with the Automation GUI as soon as the recording ends.</li></ul><h3 id="default-use-case" tabindex="-1">Default use case <a class="header-anchor" href="#default-use-case" aria-label="Permalink to “Default use case”">​</a></h3><ol><li>Open the GUI as soon as the recording ends.</li><li>Select the recording directory from the dropdown list in section 1. <ul><li>If no behavior is associated with this recording, uncheck the <strong>Is there behavior Session for Recording</strong> checkbox.</li></ul></li><li>Check the &quot;Add surgery &amp; insertion device if missing&quot; checkbox if you want to add electrode/microscope/optic fiber insertion coordinates.</li><li>Select the behavior session corresponding to the recording from the dropdown list in section 2.</li><li>Click the <strong>Register Recording</strong> button.</li></ol><figure><img src="`+o+`" alt="Automation GUI main screen" width="3682" height="2358" loading="lazy"><figcaption>Automation GUI main screen</figcaption></figure><ul><li><p>If no surgery data is found for the subject, a small form for entering surgery and device insertion coordinates appears.</p><figure><img src="`+h+`" alt="Add surgery data form" width="2448" height="1570" loading="lazy"><figcaption>Add surgery data form</figcaption></figure></li><li><p>Common coordinates for previous recordings:</p></li></ul><table tabindex="0"><thead><tr><th style="text-align:right;"><strong>Area</strong></th><th style="text-align:right;">ml(mm)</th><th style="text-align:right;">ap(mm)</th><th style="text-align:right;">depth(mm)</th><th style="text-align:right;">theta(°)</th><th style="text-align:right;">phi(°)</th><th style="text-align:right;">rho(°)</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>mPFC L HEMIS</strong></td><td style="text-align:right;">-0.6</td><td style="text-align:right;">1.8</td><td style="text-align:right;">3.8</td><td style="text-align:right;">-45</td><td style="text-align:right;">-9</td><td style="text-align:right;">180</td></tr><tr><td style="text-align:right;"><strong>mPFC R HEMIS</strong></td><td style="text-align:right;">0.6</td><td style="text-align:right;">1.8</td><td style="text-align:right;">3.8</td><td style="text-align:right;">45</td><td style="text-align:right;">9</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;"><strong>HPC L HEMIS</strong></td><td style="text-align:right;">-1.5</td><td style="text-align:right;">2</td><td style="text-align:right;">1.8</td><td style="text-align:right;">-45</td><td style="text-align:right;">-9</td><td style="text-align:right;">180</td></tr><tr><td style="text-align:right;"><strong>HPC R HEMIS</strong></td><td style="text-align:right;">1.5</td><td style="text-align:right;">2</td><td style="text-align:right;">1.8</td><td style="text-align:right;">45</td><td style="text-align:right;">9</td><td style="text-align:right;">0</td></tr></tbody></table><ul><li><p>Wait until the recording has been copied to PNI storage resources (cup).</p><figure><img src="`+l+`" alt="Dialog shown while copying session" width="794" height="176" loading="lazy"><figcaption>Dialog shown while copying session</figcaption></figure></li></ul><ol start="6"><li>After the recording has been transferred, a small dialog showing the recording ID appears.</li></ol><figure><img src="`+a+`" alt="Dialog shown when recording has been transferred" width="792" height="324" loading="lazy"><figcaption>Dialog shown when recording has been transferred</figcaption></figure><ol start="7"><li>You can check basic info about the new recording in the &quot;Recording Table&quot; tab. This tab becomes active after the recording is transferred.</li></ol><figure><img src="`+m+`" alt="Recording table tab screenshot" width="3684" height="968" loading="lazy"><figcaption>Recording table tab screenshot</figcaption></figure><h4 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h4><ul><li>This use case assumes the recording will be processed with default parameters.</li></ul><h2 id="advanced-select-parameters-use-case" tabindex="-1">&quot;Advanced&quot; (select parameters) use case <a class="header-anchor" href="#advanced-select-parameters-use-case" aria-label="Permalink to “&quot;Advanced&quot; (select parameters) use case”">​</a></h2><ol><li>Follow steps 1-4 from the <strong>Default use</strong> case.</li><li>Uncheck the <strong>&quot;Use default processing parameters for recording?&quot;</strong> checkbox.</li><li>Click the <strong>&quot;Select parameters &gt;&gt;&gt;&quot;</strong> button.</li></ol><figure><img src="`+d+`" alt="Parameter selection main screen" width="3676" height="2360" loading="lazy"><figcaption>Parameter selection main screen</figcaption></figure><ol start="4"><li>On the <strong>&quot;Select parameters&quot;</strong> tab (assuming all probes/FOVs will be processed with the same parameters):</li></ol><h3 id="on-section-1" tabindex="-1">On section 1: <a class="header-anchor" href="#on-section-1" aria-label="Permalink to “On section 1:”">​</a></h3><ol start="5"><li>In the <strong>Preprocessing Params Lists</strong> dropdown, select a preprocessing param list. <ul><li>You can see which preprocessing steps are defined for that list in the listbox on the right.</li><li>Selecting a preprocessing step in the listbox shows its specific parameters in the text area on the right.</li></ul></li></ol><h3 id="on-section-2" tabindex="-1">On section 2: <a class="header-anchor" href="#on-section-2" aria-label="Permalink to “On section 2:”">​</a></h3><ol start="6"><li>In the <strong>Processing Params</strong> dropdown, select a processing parameter set suited to the recording. <ul><li>Selecting a processing parameter set from the dropdown shows its specific parameters in the text area on the right.</li></ul></li><li>Click the <strong>Register Recording</strong> button.</li></ol><p>The next steps are identical to the <strong>&quot;Default use&quot;</strong> case.</p><h2 id="monitor-jobs" tabindex="-1">Monitor jobs <a class="header-anchor" href="#monitor-jobs" aria-label="Permalink to “Monitor jobs”">​</a></h2><ul><li><p>After a recording is submitted for processing, you can track, reprocess, and visualize all jobs corresponding to that recording.</p><figure><img src="`+i+`" alt="Manage Processing Jobs main screen" width="3680" height="2364" loading="lazy"><figcaption>Manage Processing Jobs main screen</figcaption></figure></li></ul><h3 id="track-status" tabindex="-1">Track status <a class="header-anchor" href="#track-status" aria-label="Permalink to “Track status”">​</a></h3><ol><li>Switch to the <strong>&quot;Manage Processing Jobs&quot;</strong> tab.</li><li>Use the <strong>&quot;User&quot;</strong>, <strong>&quot;Subject&quot;</strong>, and <strong>&quot;Date&quot;</strong> dropdowns/fields to find the desired jobs.</li><li>Select the row corresponding to the desired job:</li></ol><ul><li>The job status history is shown for the selected job.</li></ul><h4 id="if-status-of-job-is-in-error-status-1-2-error-in-recording-process" tabindex="-1">If the job is in an error status (-1, -2; &quot;Error in recording process&quot;): <a class="header-anchor" href="#if-status-of-job-is-in-error-status-1-2-error-in-recording-process" aria-label="Permalink to “If the job is in an error status (-1, -2; &quot;Error in recording process&quot;):”">​</a></h4><ul><li>Open the error log file in the bottom-right corner by clicking the <strong>&quot;Open Error Log File&quot;</strong> button.</li><li>If you believe the cause of the error is now resolved, rerun the job by clicking the <strong>&quot;Rerun job&quot;</strong> button.</li></ul><h4 id="if-status-of-job-is-in-finished-status-7-8-data-in-element-db" tabindex="-1">If the job is in a finished status (7, 8; &quot;Data in element DB&quot;): <a class="header-anchor" href="#if-status-of-job-is-in-finished-status-7-8-data-in-element-db" aria-label="Permalink to “If the job is in a finished status (7, 8; &quot;Data in element DB&quot;):”">​</a></h4><ul><li><p>Open the output log file in the bottom-right corner by clicking the <strong>&quot;Open Output Log File&quot;</strong> button.</p></li><li><p>Visualize processing results by clicking the bottom-right buttons: <strong>Open Phy</strong> and <strong>Open IBL Atlas</strong> for ephys, <strong>Open Suite2p-GUI</strong> for imaging.</p><figure><img src="`+c+`" alt="Visualization tools available" width="2774" height="1328" loading="lazy"><figcaption>Visualization tools available</figcaption></figure></li></ul><h4 id="rerun-jobs" tabindex="-1">Rerun jobs <a class="header-anchor" href="#rerun-jobs" aria-label="Permalink to “Rerun jobs”">​</a></h4><ul><li>You can rerun a job with different parameters by clicking the <strong>New Job With different Parameters</strong> button.</li><li>Follow the <a href="/software/automation_pipeline.html#advanced-select-parameters-use-case"> &quot;Advanced&quot; (select parameters) use case </a>.</li></ul><h2 id="create-new-sets-of-processing-parameters-for-recordings" tabindex="-1">Create new sets of processing parameters for recordings <a class="header-anchor" href="#create-new-sets-of-processing-parameters-for-recordings" aria-label="Permalink to “Create new sets of processing parameters for recordings”">​</a></h2><p>To process recordings with non-default parameters, you need at least one of the following:</p><ol><li>A new set of processing parameters (parameters for the algorithm that processes the data, e.g. Kilosort, Suite2p).</li><li>A list of preprocessing steps, each with its own set of preprocessing parameters (e.g. run CatGT + TPrime before Kilosort).</li></ol><figure><img src="`+p+`" alt="Create parameters screen" width="3686" height="2364" loading="lazy"><figcaption>Create parameters screen</figcaption></figure><h3 id="create-new-processing-parameters-algorithm-params" tabindex="-1">Create new Processing parameters (algorithm params) <a class="header-anchor" href="#create-new-processing-parameters-algorithm-params" aria-label="Permalink to “Create new Processing parameters (algorithm params)”">​</a></h3><ul><li>Note: You need a JSON file with all parameters ready before starting this process.</li><li><a href="./assets/files/automation_gui/kilosort_parameters_example.json.zip">Here</a> is an example Kilosort parameter JSON file that you can use as a template for your own.</li></ul><ol><li>Switch to the &quot;Create Parameters&quot; tab.</li></ol><h4 id="on-section-0" tabindex="-1">On section 0: <a class="header-anchor" href="#on-section-0" aria-label="Permalink to “On section 0:”">​</a></h4><ol start="2"><li>In the &quot;recording modality&quot; dropdown, select which modality the parameters correspond to.</li><li>In the &quot;user&quot; dropdown, select your NETID username (select general-user if this parameter will be shared by many users).</li></ol><h4 id="on-section-1a" tabindex="-1">On section 1a: <a class="header-anchor" href="#on-section-1a" aria-label="Permalink to “On section 1a:”">​</a></h4><ol start="4"><li>In the &quot;proc. Param Method&quot; dropdown, select which method (algorithm) these parameters refer to.</li></ol><h5 id="if-the-algorithm-is-not-found-on-proc-param-method-dropdown" tabindex="-1">If the algorithm is not found on &quot;proc. Param Method&quot; dropdown: <a class="header-anchor" href="#if-the-algorithm-is-not-found-on-proc-param-method-dropdown" aria-label="Permalink to “If the algorithm is not found on &quot;proc. Param Method&quot; dropdown:”">​</a></h5><ul><li>Check the &quot;define new proc. param method ?&quot; checkbox.</li><li>Write the new processing method name in the &quot;New Proc. Param. method&quot; field.</li><li>Check the <a href="/software/automation_pipeline_developer.html#collab-repositories-to-handle-ephys-imaging-processing">automation pipeline developer guide</a> to add the corresponding processing code.</li></ul><ol start="5"><li>In the &quot;proc. Param Set Description&quot; field, write a short description for the new parameters.</li><li>Click the &quot;Upload Proc-Parm Set json file&quot; button and browse for/load your JSON file with parameters. You can review your parameters in the text area on the right.</li><li>Click the &quot;Register Proc. Param Set&quot; button.</li></ol><h3 id="create-new-preprocessing-parameters-a-single-step-on-preprocessing-list" tabindex="-1">Create new preprocessing parameters (a single step on preprocessing list) <a class="header-anchor" href="#create-new-preprocessing-parameters-a-single-step-on-preprocessing-list" aria-label="Permalink to “Create new preprocessing parameters (a single step on preprocessing list)”">​</a></h3><ul><li>Note: You need a JSON file with all parameters ready before starting this process.</li><li><a href="./assets/files/automation_gui/catgt_parameters_example.json.zip">Here</a> is an example CatGT parameter JSON file that you can use as a template for your own.</li></ul><ol><li>Switch to the &quot;Create Parameters&quot; tab.</li></ol><h3 id="on-section-0-1" tabindex="-1">On section 0: <a class="header-anchor" href="#on-section-0-1" aria-label="Permalink to “On section 0:”">​</a></h3><ol start="2"><li>In the &quot;recording modality&quot; dropdown, select which modality the parameters correspond to.</li><li>In the &quot;user&quot; dropdown, select your NETID username (select general-user if this parameter will be shared by many users).</li></ol><h3 id="on-section-1b" tabindex="-1">On section 1b: <a class="header-anchor" href="#on-section-1b" aria-label="Permalink to “On section 1b:”">​</a></h3><ol start="4"><li>In the &quot;Preproc.-Param Method&quot; dropdown, select which method (tool) these parameters refer to.</li></ol><h4 id="if-the-tool-is-not-found-on-preproc-param-method-dropdown" tabindex="-1">If the tool is not found on &quot;Preproc.-Param Method&quot; dropdown: <a class="header-anchor" href="#if-the-tool-is-not-found-on-preproc-param-method-dropdown" aria-label="Permalink to “If the tool is not found on &quot;Preproc.-Param Method&quot; dropdown:”">​</a></h4><ul><li>Check the &quot;define new prerproc.-param method ?&quot; checkbox.</li><li>Write the new preprocessing method name in the &quot;New Preproc.-Param method&quot; field.</li><li>Check the <a href="/software/automation_pipeline_developer.html#collab-repositories-to-handle-ephys-imaging-processing">automation pipeline developer guide</a> to add the corresponding processing code.</li></ul><ol start="5"><li>In the &quot;Preproc.-Param Set Description&quot; field, write a short description for the new parameters.</li><li>Click the &quot;Upload Preproc.-Parm Set json file&quot; button and browse for/load your JSON file with parameters. You can review your parameters in the text area on the right.</li><li>Click the &quot;Register PreProc. Param Set&quot; button.</li></ol><h3 id="create-new-preprocessing-parameters-list-a-set-of-preprocessing-parameters" tabindex="-1">Create new preprocessing parameters list (a set of preprocessing parameters) <a class="header-anchor" href="#create-new-preprocessing-parameters-list-a-set-of-preprocessing-parameters" aria-label="Permalink to “Create new preprocessing parameters list (a set of preprocessing parameters)”">​</a></h3><ul><li>Note: If you just created a preprocessing parameter, restart the GUI.</li></ul><ol><li>Switch to the &quot;Create Parameters&quot; tab.</li></ol><h3 id="on-section-0-2" tabindex="-1">On section 0: <a class="header-anchor" href="#on-section-0-2" aria-label="Permalink to “On section 0:”">​</a></h3><ol start="2"><li>In the &quot;recording modality&quot; dropdown, select which modality the parameters correspond to.</li><li>In the &quot;user&quot; dropdown, select your NETID username (select general-user if this parameter will be shared by many users).</li></ol><h3 id="on-section-1c" tabindex="-1">On section 1c: <a class="header-anchor" href="#on-section-1c" aria-label="Permalink to “On section 1c:”">​</a></h3><ol start="4"><li>In the &quot;Pre-Params List Name&quot; field, enter a suitable name for the list.</li><li>In the &quot;Pre.-Param List Description&quot; field, write a short description for the new list.</li><li>From the &quot;Pre.-Params steps&quot; dropdown, select the desired preprocessing step to add to the list.</li><li>Click the &quot;Add Preparam Steps&quot; button.</li><li>Repeat steps 6 and 7 to add all desired preprocessing steps to the list.</li><li>Use the &quot;v&quot; and &quot;^&quot; buttons to set the order of the preprocessing steps.</li><li>Use the &quot;x&quot; button to delete an unwanted preprocessing step.</li><li>Click the &quot;Register pre param list&quot; button.</li></ol>`,76)]])}var y=n(_,[[`render`,v]]);export{g as __pageData,y as default};